def transform(grid):
    h, w = len(grid), len(grid[0])
    sep = None

    # The separator divides the grid into equal-sized panels.
    for r in range(h):
        if len(set(grid[r])) == 1 and r == h - r - 1:
            sep = ("h", r)
            break
    if sep is None:
        for c in range(w):
            if len({grid[r][c] for r in range(h)}) == 1 and c == w - c - 1:
                sep = ("v", c)
                break

    if sep is None:
        return [row[:] for row in grid]

    axis, k = sep
    if axis == "h":
        a, b = grid[:k], grid[k + 1:]
    else:
        a = [row[:k] for row in grid]
        b = [row[k + 1:] for row in grid]

    from collections import Counter
    counts = Counter(v for row in a + b for v in row)
    bg = counts.most_common(1)[0][0]

    if axis == "h":
        return [[3 if a[r][c] == b[r][c] else bg
                 for c in range(w)] for r in range(len(a))]
    return [[3 if a[r][c] == b[r][c] else bg
             for c in range(len(a[0]))] for r in range(h)]
